// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge as C} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    // Fuzz parameters: address player and a bytes32 guessHash
    function testFuzz_property(address player, bytes32 guessHash) public {
        player = address(uint160(bound(uint256(uint160(player)), 0xffff + 1, type(uint160).max)));
        vm.assume(player.code.length == 0 && player != address(this) && player != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && player != 0x000000000000000000636F6e736F6c652e6c6f67 && player != 0x4e59b44847b379578588920cA78FbF26c0B4956C && player != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        // keep player non-zero and distinct from this contract
        vm.assume(player != address(0));
        vm.assume(player != address(this));

        // fund the player so they can send 1 ether for lockInGuess
        vm.deal(player, 2 ether);

        // Player locks in a guess in the next block number (we must call lockInGuess first)
        vm.prank(player);
        // lockInGuess requires exactly 1 ether
        c.lockInGuess{value: 1 ether}(guessHash);

        // Now attempt to call settle in the SAME block as lockInGuess: to simulate this in a test
        // we must ensure both calls occur in the same block. Foundry executes sequentially in the same block
        // unless vm.roll or vm.warp are used. We DO NOT advance the block, so this models trying to settle in same block.
        bool ok;
        try c.settle{gas: gasleft()}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General property (single assertion): On the correct reference implementation, settle() MUST revert
        // (i.e., not succeed) when called in the same block as the lock (require(block.number > guesses[msg.sender].block)).
        // The mutant changing to '>=' will allow success for some inputs; thus the assertion will fail for the mutant.
        assertTrue(!ok);
    }
}
